//! depleted. The combat log's END success flag only means "completed", so
//! the timed verdict needs this table.

/// A keystone dungeon's (par, +2, +3) timers, in milliseconds.
pub(crate) fn pars_ms(challenge_id: u32) -> Option<(i64, i64, i64)> {
    let i = TABLE.binary_search_by_key(&challenge_id, |e| e.0).ok()?;
    let &(_, _, par, plus2, plus3) = TABLE.get(i)?;
    Some((par, plus2, plus3))
}

/// The timers of the one keystone dungeon on `map_id` — what a key joined
/// mid-run gets, since its END carries the map and no challengeID. A map
/// holding two challenge modes (a split dungeon) is ambiguous: `None`.
pub(crate) fn pars_for_map(map_id: u32) -> Option<(i64, i64, i64)> {
    let mut on_map = TABLE.iter().filter(|e| e.1 == map_id);
    let &(_, _, par, plus2, plus3) = on_map.next()?;
    on_map.next().is_none().then_some((par, plus2, plus3))
}

