#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted_by_challenge_id() {
        assert!(TABLE.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn timers_are_plausible_and_descending() {
        // Pars between 10 minutes and 2 hours (legacy challenge modes reach
        // 85:00), +3 <= +2 <= par — a tripwire against the DB2 columns
        // changing meaning under us.
        assert!(TABLE.iter().all(|e| (600_000..7_200_000).contains(&e.2)));
        assert!(TABLE.iter().all(|e| e.4 <= e.3 && e.3 <= e.2));
    }

    #[test]
    fn a_map_finds_its_one_dungeon_and_a_split_map_finds_none() {
        for e in TABLE.iter() {
            let twins = TABLE.iter().filter(|o| o.1 == e.1).count();
            let want = (twins == 1).then_some((e.2, e.3, e.4));
            assert_eq!(pars_for_map(e.1), want, "map {}", e.1);
        }
        assert_eq!(pars_for_map(0), None);
    }
}
